      "広背筋にアプローチするナローチンニングを含む多様なチンニングが可能。従来のぶら下がり健康器や懸垂バー（チンニングバー / pull up bar）以上に幅広いトレーニングをこのチンニングスタンドでお楽しみいただけます。",
