      "■コンパクトでシンプル。天井高が低い場所にも設置しやすいスミスマシン。 ■高さ約195cmと低めの設計。 ■スミスバー内寸サイズ：約117.5cm ■グリップ部分はローレット加工仕上げ。 ■スライドフレームはベアリング使用で動きもスムーズ。 ■バーベルフックは8.5cm間隔の調節。 ■高強度スプリングとラバークッションが衝撃を緩和。",
      "■使用出来るプレート（重り）は穴径29mmのレギュラープレートが標準です。 ■標準スリーブの長さ：約31cm ■プレート収納ホルダーも標準は",
      "穴径29mmレギュラープレート専用です。 ■付属のオリンピックプレート専用ホルダーを装着することにより",
      "穴径51mmのオリンピックプレートも使用出来ます。 ■スミスバーを1番上に掛けた際の高さ：約168.4cm ■セイフティフックを1番下に掛けた際の高さ：約56.3cm ■手首でバーベルを返すことで簡単にバーベルを置くことができます。",
      "■スライドフレームはベアリングを使用している為",
      "動きもスムーズ。 ※ベアリング仕様の為",
