      "予めご了承下さい。",
      "■本体サイズ：D約125cm×W約194.5cm×H約195cm ■本体重量：約76.3kg（オリンピックスリーブを装着した時の重量：約80kg） ※ウエイトプレート（重り）・ベンチは別売りです。",
      "■当該製品は『組立式』です。商品の組立はお客様ご自身で行っていただきます。 ■当社からの組立サービスは一切行っておりません。 ■工具は付属していませんので",
