      "またはエレベーター等が無い集合住宅の場合は1Fエントランスでの受け渡しとなる場合が御座います。 ■当製品は『家庭用』の為",
      "不特定多数の方がご使用になられる会社・学校・スポーツジム・パーソナルジム・医療介護施設・整骨院等でのご使用は出来ません。 ■お届けいたしました製品に万が一",
      "初期不良および欠品等があった場合のご対応は宅急便またはネコポス便等にて行います。 ■部品などのお届けに2日から4日ほど日数がかかりますのでご了承ください。 ■お届けより7日間を経過した場合のクレーム等は",
      "一切お受け致しません。（ご到着後7日以内に商品のご確認をお願い致します） ■一度",
