    "productDescription": "IROTEC（アイロテック）パワースミスマシン ■コンパクトでシンプル。天井高が低い場所にも設置しやすいスミスマシンです。 ■高さは約195cmと低く設計。 ■スミスバー内寸サイズ：約117.5cm ■グリップ部分はローレット加工仕上げ。 ■スライドフレームはベアリング使用で動きもスムーズ。 ■バーベルフックは8.5cm間隔で調節が可能。 ■高強度スプリングとラバークッションが衝撃を緩和。 ■使用出来るプレート（重り）は穴径29mmのレギュラープレートが標準です。 ■標準スリーブの長さ：約31cm ■プレート収納ホルダーも標準は、穴径29mmレギュラープレート専用です。 ■付属のオリンピックプレート専用ホルダーを装着することにより、穴径51mmのオリンピックプレートも使用出来ます。 ■スミスバーを1番上に掛けた際の高さ：約168.4cm ■セイフティフックを1番下に掛けた際の高さ：約56.3cm ■スライドフレームはベアリングを使用している為、動きもスムーズ。 ※ベアリング仕様の為、スライドフレームが上下する際ベアリング音が発生致します。 仕様であり不具合では御座いません、予めご了承下さい。 ■手首でバーベルを返すことで簡単にバーベルを置くことができます。 ■本体サイズ：D約125cm×W約194.5cm×H約195cm ■本体重量：約76.3kg（オリンピックスリーブを装着した時の重量：約80kg） ※ウエイトプレート（重り）・ベンチは別売りです。 ■当該製品は『組立式』です。商品の組立はお客様ご自身で行っていただきます。 ■当社からの組立サービスは一切行っておりません。 ■工具は付属していませんので、お客様ご自身で組立に必要な工具をご用意ください。 ■組立には危険が伴いますので必ず2人以上で十分注意して組立を行ってください。 ■商品の受け渡しは玄関先までとなり、またはエレベーター等が無い集合住宅の場合は1Fエントランスでの受け渡しとなる場合が御座います。 ■当製品は『家庭用』の為、不特定多数の方がご使用になられる会社・学校・スポーツジム・パーソナルジム・医療介護施設・整骨院等でのご使用は出来ません。 ■お届けいたしました製品に万が一、初期不良および欠品等があった場合のご対応は宅急便またはネコポス便等にて行います。 ■改良等により、予告なく商品の形状、色、仕様が変更する場合がございます。 ■製造ロットにより、商品の形状、色、仕様が変更する場合がございます。 ■安全にご使用いいただく為、改造等は絶対におやめください。 ■パーツ内部に製造加工過程で使用する砂鉄が残留するケースがございます。組み立ての際に砂鉄がこぼれ落ちるケースがございますので、予めご了承下さいませ。 ■海外輸入品のため、輸送時に多少のキズ・凹みがある場合がございます。予めご了承下さいませ。",
