      "availability": "残り4点 ご注文はお早めに 在庫状況 について",
      "featureBullets": "【11段階調節可能】懸垂器具高さの順次には：223CM/218CM/213CM/207CM/202CM/197CM/191CM/186CM/180CM/175CM/170CM マシンの高さは身長に合わせて調節できます。★懸垂マシンの本体重量：約13kg ★ぶら下がりの本体寸法：幅69cmX奥63.5cmX高70cm～223.5cm(チンニングスタンド高さ11段階調節可能) ★最大耐荷重制限:85kg\n【家庭向けのスリムな設計】家に置く物を意識してサイズを設計しております。生活の邪魔をせず、人1人の肩幅にちょうど良いサイズとなっております。ちょっとしたスペースに置けるコンパクトの仕上がりになっているので、省スペースで使いたい方におすすめです。他にも、ぶら下がり健康器デビューの方や、本格派を買っても続くか不安な方にもおすすめの製品となっております。\n【強度と安定性に優れた設計】従来品よりパイプの厚みを約42％UPし、2.0mmになりました。さらに、H型4点支え支柱で力が分散する事で負担を軽減。強度UPによりがっちり支えることで揺れやぐらつきが少なく、ストレスのないトレーニングを実現できます。 また、固定ボルトはWロック方式を採用。2本のボルトで支柱を固定し、頑丈さをUPしました。しっかり固定で安心してぶら下がっていただけます。土台はあえて大きくしており、しっかりと地面に接地するので、揺れやガタツキを防ぎ使用中に生じる不快な縦揺れを軽減します。\n【ストレッチやトレーニングにも】懸垂部の高さ調節11段階はもちろんのこと、アームレストや腕立てグリップ＆バーも付いています。腕立てグリップは腕立て、バーは腹筋などのトレーニングができます。アームレストはレッグレイズのサポートをしてくれます。長さの調節も可能です。ぶら下がるだけでなく、様々なトレーニングを強化できるパーツが設置されています。"
